-- READ ONLY. Safe to run: it only reads the catalogue (no business rows, no changes).
-- Purpose: compare a candidate dry-run project ("EES Development", ref wpmnjfncaoogssgpqxek) with the production project (ref hafoaurzfgkkwpvzedvd)
-- BEFORE using it to rehearse Stage 0. Run it in each project's SQL editor and compare the two result sets line by line.
-- The dry run is only meaningful if every line below matches. The production baseline captured on 2026-11-06 is in reports/2026-11-06-stage0-preflight.md.

select 'a_server_version_major' as check_name, split_part(current_setting('server_version'), '.', 1) as value
union all select 'b_public_table_count', count(*)::text from pg_class c join pg_namespace n on n.oid = c.relnamespace where n.nspname = 'public' and c.relkind = 'r'
union all select 'c_public_table_names_md5', md5(coalesce(string_agg(c.relname, ',' order by c.relname), '')) from pg_class c join pg_namespace n on n.oid = c.relnamespace where n.nspname = 'public' and c.relkind = 'r'
union all select 'd_rls_enabled_count', count(*)::text from pg_class c join pg_namespace n on n.oid = c.relnamespace where n.nspname = 'public' and c.relkind = 'r' and c.relrowsecurity
union all select 'e_rls_disabled_tables', coalesce(string_agg(c.relname, ',' order by c.relname), '(none)') from pg_class c join pg_namespace n on n.oid = c.relnamespace where n.nspname = 'public' and c.relkind = 'r' and not c.relrowsecurity
union all select 'f_anon_privileges_on_the_15', coalesce((select string_agg(x.relname || ':' || x.privs, ' ; ' order by x.relname) from (select c.relname, string_agg(a.privilege_type, ',' order by a.privilege_type) as privs from pg_class c join pg_namespace n on n.oid = c.relnamespace cross join lateral aclexplode(c.relacl) a where n.nspname = 'public' and a.grantee::regrole::text = 'anon' and c.relname in ('bank_transfers','drivers','fuel_logs','oil_change_baselines','oil_change_history','shipments','trip_fuel_logs','trip_journeys','vehicle_safety_assets','vehicle_safety_inspection_items','vehicle_safety_inspections','vehicle_safety_issues','vehicle_safety_requirements','vehicles','weekly_mileage') group by c.relname) x), '(none)')
union all select 'g_policy_count_total', count(*)::text from pg_policies where schemaname = 'public'
union all select 'h_policies_on_the_three_inert_tables', coalesce((select string_agg(tablename || '=' || n::text, ', ' order by tablename) from (select tablename, count(*) n from pg_policies where schemaname = 'public' and tablename in ('oil_change_baselines','oil_change_history','vehicles') group by tablename) t), '(none)')
union all select 'i_helper_functions', coalesce((select string_agg(p.proname || '(secdef=' || p.prosecdef::text || ')', ', ' order by p.proname) from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname in ('current_account_role','is_account_active','is_account_admin','is_office_account','is_support_ticket_admin')), '(none found)')
union all select 'j_account_access_role_check', coalesce((select string_agg(pg_get_constraintdef(oid), ' ; ' order by oid) from pg_constraint where conrelid = 'public.account_access'::regclass and contype = 'c'), '(account_access missing)')
union all select 'k_default_privileges_public', coalesce((select string_agg(pg_get_userbyid(defaclrole) || ' ' || defaclobjtype::text || ' => ' || defaclacl::text, ' ; ' order by 1) from pg_default_acl d join pg_namespace n on n.oid = d.defaclnamespace where n.nspname = 'public'), '(none)')
union all select 'l_custom_roles', coalesce((select string_agg(rolname, ',' order by rolname) from pg_roles where rolname !~ '^(pg_|supabase_|postgres$|anon$|authenticated$|service_role$|authenticator$|dashboard_user$|cli_login)'), '(none)')
union all select 'm_anon_executable_security_definer_functions', count(*)::text from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.prosecdef and has_function_privilege('anon', p.oid, 'EXECUTE')
union all select 'n_booking_diary_key_columns', coalesce((select string_agg(column_name || ':' || data_type, ', ' order by column_name) from information_schema.columns where table_schema = 'public' and table_name = 'booking_diary' and column_name in ('id','vehicle_id','driver_id','booking_id','pickup_time')), '(none)')
union all select 'o_signup_trigger_present', (select (count(*) > 0)::text from pg_trigger where tgfoid = 'public.create_default_account_access_for_new_user'::regproc and not tgisinternal)
order by 1;
